function saved<T>(key:string,fallback:T):[T,React.Dispatch<React.SetStateAction<T>>]{const[v,setV]=useState<T>(()=>{try{return JSON.parse(localStorage.getItem(key)||'null')??fallback}catch{return fallback}});useEffect(()=>{try{const safe=key==='piper.recipes'&&Array.isArray(v)?(v as any[]).map(r=>({...r,image:typeof r.image==='string'&&r.image.startsWith('data:')?'':r.image})):v;localStorage.setItem(key,JSON.stringify(safe))}catch(e){console.warn('Piper local save skipped',e)}},[key,v]);return[v,setV]}
