const syncPantry=useMemo(()=>pantry.filter(x=>x.inStock).map<Grocery>(x=>({id:'pantry-'+x.id,name:x.name,qty:'1',category:x.category,aisle:x.category==='Household'?'Household':'Pantry',price:x.price,store:x.store,checked:false,source:'Pantry'})),[pantry]);
  const cloudState=useMemo(()=>({pantry,groceries,prefs,plan,onboarded,budget,version:2}),[pantry,groceries,prefs,plan,onboarded,budget]);
  useEffect(()=>onAuthStateChanged(auth,async user=>{setFirebaseUser(user);setCloudReady(false);setCloudMessage('');cloudRecipeIds.current.clear();cloudRecipeHashes.current.clear();if(!user)return;try{const cloud=await loadCloud(user.uid);if(cloud.state){const state:any=cloud.state;if(Array.isArray(state.pantry))setPantry(state.pantry);if(Array.isArray(state.groceries))setGroceries(state.groceries);if(state.prefs)setPrefs(state.prefs);if(state.plan)setPlan(state.plan);if(typeof state.budget==='number')setBudget(state.budget);const cloudRecipes=cloud.recipes as Recipe[];cloudRecipes.forEach(r=>{cloudRecipeIds.current.add(r.id);if(typeof (r as any).familyPrivate==='boolean')cloudRecipeHashes.current.set(r.id,recipeFingerprint(r))});hydrateLocalPhotos(cloudRecipes).then(hydrated=>setRecipes(hydrated as Recipe[]));setCloudMessage('Synced with your Piper account.');if(returningSignIn.current||!onboarded){returningSignIn.current=false;setOnboarded(true);setTour(false);setPage('recipes')}}else{setMigrationOpen(true);if(returningSignIn.current){returningSignIn.current=false;setOnboarded(true);setTour(false);setPage('recipes')}}}catch(e:any){setCloudMessage('Cloud sync could not load: '+String(e.message||e))}finally{setCloudReady(true)}}),[]);
  useEffect(()=>{if(!firebaseUser||!cloudReady||migrationOpen)return;const timer=setTimeout(()=>saveCloudState(firebaseUser.uid,cloudState).then(()=>setCloudMessage('Saved to your Piper account.')).catch(e=>setCloudMessage('Cloud save failed: '+String(e.message||e))),900);return()=>clearTimeout(timer)},[cloudState,firebaseUser,cloudReady,migrationOpen]);
  useEffect(()=>{if(!firebaseUser||!cloudReady||migrationOpen)return;const timer=setTimeout(()=>syncChangedRecipes(firebaseUser.uid,recipes,cloudRecipeIds.current,cloudRecipeHashes.current).then(count=>{if(count)setCloudMessage(`${count} recipe change${count===1?'':'s'} synced.`)}).catch(e=>setCloudMessage('Recipe sync failed: '+String(e.message||e))),1200);return()=>clearTimeout(timer)},[recipes,firebaseUser,cloudReady,migrationOpen]);
  async function uploadCurrentKitchen(){if(!firebaseUser)return;setCloudMessage('Uploading this device’s Piper kitchen…');await saveCloudState(firebaseUser.uid,cloudState);await importRecipesInBatches(firebaseUser.uid,recipes,(phase,current,total)=>setCloudMessage(`${phase}: ${current}/${total}`));recipes.forEach(r=>{cloudRecipeIds.current.add(r.id);cloudRecipeHashes.current.set(r.id,recipeFingerprint(r))});setMigrationOpen(false);setCloudReady(true);setCloudMessage('This device’s Piper kitchen is now synced. Imported photos remain compressed on this device.');}
  async function importCopyRecipes(incoming:CopyMeThatRecipe[],onProgress:(p:{phase:string;current:number;total:number;percent:number})=>void){setCloudMessage('Importing recipes and cloud photos…');const converted:Recipe[]=[];let uploaded=0,localOnly=0;const total=incoming.length;for(let i=0;i<total;i++){const source=incoming[i];let image=source.image;if(image?.startsWith('data:image/')){onProgress({phase:'Uploading compressed photos to cloud',current:i+1,total,percent:25+Math.round(((i+1)/Math.max(1,total))*55)});try{image=await uploadRecipePhoto(image,source.id);uploaded++}catch(error){await saveLocalPhoto(source.id,image);localOnly++;console.warn('Cloud photo upload failed; retained locally',source.title,error)}}converted.push({...source,image});if((i+1)%10===0)await new Promise(resolve=>setTimeout(resolve,0))}onProgress({phase:'Saving recipe records',current:0,total,percent:82});await importRecipesInBatches(firebaseUser?.uid,converted,(phase,current,totalCount,percent)=>onProgress({phase,current,total:totalCount,percent:82+Math.round((percent/100)*16)}));setRecipes(current=>[...converted,...current.filter(old=>!converted.some(n=>n.title.trim().toLowerCase()===old.title.trim().toLowerCase()))]);converted.forEach(r=>{if(firebaseUser){cloudRecipeIds.current.add(r.id);cloudRecipeHashes.current.set(r.id,recipeFingerprint(r))}});setMigrationOpen(false);setCloudReady(true);setCloudMessage(`${total} recipes imported. ${uploaded} photos available on every signed-in device${localOnly?`; ${localOnly} photo${localOnly===1?' remains':'s remain'} local because upload failed`:''}.`);onProgress({phase:'Done',current:total,total,percent:100})} 
useEffect(()=>{if(!isFeedbackAdmin){setAdminFeedback([]);return}let live=true;const refresh=()=>loadBetaFeedback().then((reports:BetaFeedbackReport[])=>{if(live)setAdminFeedback(reports)}).catch((error:unknown)=>console.warn('Feedback inbox refresh skipped',error));void refresh();const t=setInterval(refresh,20000);return()=>{live=false;clearInterval(t)}},[isFeedbackAdmin]);
