let toastHost:((m:string)=>void)|null=null;
function showToast(m:string){toastHost?.(m)}
function ToastHost(){const[msg,setMsg]=useState('');useEffect(()=>{toastHost=m=>setMsg(m);return()=>{toastHost=null}},[]);useEffect(()=>{if(!msg)return;const t=setTimeout(()=>setMsg(''),2800);return()=>clearTimeout(t)},[msg]);return msg?<div className="grocery-toast app-toast" role="status">{msg}</div>:null}
const isNative=()=>{try{return Capacitor.isNativePlatform()}catch{return false}};
const platformName=()=>{try{return Capacitor.getPlatform()}catch{return'web'}};
async function shareText(o:{title:string;text:string;dialogTitle?:string}):Promise<'shared'|'copied'|'cancelled'|'failed'>{
 try{if(isNative()){await Share.share({title:o.title,text:o.text,dialogTitle:o.dialogTitle||'Share'});return'shared'}const nav=navigator as any;if(nav.share){await nav.share({title:o.title,text:o.text});return'shared'}}
 catch(e:any){if(/cancel|abort/i.test(String(e?.message||'')+String(e?.name||'')))return'cancelled'}
 try{await navigator.clipboard.writeText(o.text);return'copied'}catch{return'failed'}}
function recipeShareText(r:Recipe,scale=1):string{const sc=scale===1?'':` (${scale===.5?'½':scale}×)`;const serves=Math.round((r.servings||4)*scale*100)/100;const out:string[]=[r.title+sc,[r.time?`${r.time} min`:'',`Serves ${serves}`].filter(Boolean).join(' · '),''];if(r.description?.trim())out.push(r.description.trim(),'');out.push('INGREDIENTS');(r.ingredients||[]).forEach(x=>out.push('• '+scaleIngredient(x,scale)));out.push('','DIRECTIONS');(r.instructions||[]).forEach((x,i)=>out.push(`${i+1}. ${x}`));out.push('');if(isChef(r))out.push('Created with Piper’s Chef');else if(r.sourceUrl)out.push(`Original recipe${r.sourceName?' from '+r.sourceName:''}:`,r.sourceUrl);out.push('Shared from Piper · Good food, made easier.');return out.join('\n')}
async function shareRecipe(r:Recipe,scale=1){const res=await shareText({title:r.title,text:recipeShareText(r,scale),dialogTitle:'Share recipe'});if(res==='copied')showToast('Recipe copied. Paste it into a message.');else if(res==='failed')showToast('Sharing is not available on this device.')}
function diagnostics(){return{appVersion:APP_VERSION,build:APP_BUILD,channel:APP_CHANNEL,platform:platformName(),native:isNative(),screen:`${window.innerWidth}x${window.innerHeight}`,pixelRatio:Math.round((window.devicePixelRatio||1)*100)/100,language:navigator.language||'',userAgent:String(navigator.userAgent||'').slice(0,300),online:navigator.onLine}}
const FEEDBACK_KINDS:[string,string][]=[['bug','🐛 Something isn’t working'],['idea','💡 Idea or suggestion'],['look','🎨 Something looks wrong'],['love','❤️ Something I like'],['other','Other']];
const FEEDBACK_AREAS=['Recipes','Planner','Grocery','Pantry','Discover','Prefs','Cook mode','Importing recipes','Sign in or sync','Other'];
function niceDate(n:number){try{return new Date(n).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}catch{return''}}
function AdminFeedbackInbox({items,setItems,close}:{items:BetaFeedbackReport[];setItems:React.Dispatch<React.SetStateAction<BetaFeedbackReport[]>>;close:()=>void}){const[filter,setFilter]=useState<'new'|'reviewing'|'fixed'|'all'>('new');const[busy,setBusy]=useState('');const shown=items.filter(x=>filter==='all'||x.status===filter);const counts=(v:string)=>items.filter(x=>x.status===v).length;
 async function status(r:BetaFeedbackReport,v:'new'|'reviewing'|'fixed'){setBusy(r.id);try{await setBetaFeedbackStatus(r.id,v);setItems(xs=>xs.map(x=>x.id===r.id?{...x,status:v}:x))}catch{showToast('Could not update that report.')}finally{setBusy('')}}
 return <div className="modal admin-feedback-modal" role="dialog" aria-modal="true"><div className="modal-card admin-feedback"><div className="modal-head"><div><h2>Beta Feedback</h2><p>{counts('new')} new · {items.length} total</p></div><button aria-label="Close" onClick={close}><X/></button></div><div className="feedback-filters">{(['new','reviewing','fixed','all'] as const).map(v=><button key={v} className={filter===v?'on':''} onClick={()=>setFilter(v)}>{v==='new'?`New (${counts('new')})`:v==='reviewing'?`Reviewing (${counts('reviewing')})`:v==='fixed'?`Fixed (${counts('fixed')})`:`All (${items.length})`}</button>)}</div>{shown.length?<div className="feedback-inbox">{shown.map(r=><article key={r.id} className={`feedback-report ${r.status}`}><div className="feedback-report-head"><b>{r.category==='bug'?'🐛 Bug':r.category==='idea'?'💡 Idea':r.category==='look'?'🎨 Visual':r.category==='love'?'❤️ Like':'Feedback'}</b><span>{niceDate(r.createdAt)}</span></div><p>{r.message}</p><div className="feedback-meta"><span>{r.area||'Area not specified'}</span><span>{r.email||'No email'}</span>{r.diagnostics&&<span>{String((r.diagnostics as any).platform||'')} · {String((r.diagnostics as any).build||'')}</span>}</div><div className="feedback-status-actions"><button disabled={busy===r.id||r.status==='new'} onClick={()=>void status(r,'new')}>New</button><button disabled={busy===r.id||r.status==='reviewing'} onClick={()=>void status(r,'reviewing')}>Reviewing</button><button disabled={busy===r.id||r.status==='fixed'} onClick={()=>void status(r,'fixed')}>Fixed</button></div></article>)}</div>:<div className="feedback-empty"><Check/><b>No {filter==='all'?'feedback':filter+' feedback'} here.</b></div>}</div></div>}
function FeedbackModal({user,close}:{user:User|null;close:()=>void}){const[kind,setKind]=useState('bug');const[area,setArea]=useState('');const[msg,setMsg]=useState('');const[diag,setDiag]=useState(true);const[busy,setBusy]=useState(false);const[err,setErr]=useState('');const[done,setDone]=useState(false);
 async function send(){const text=msg.trim();if(text.length<3||!user)return;setBusy(true);setErr('');try{await saveBetaFeedback({uid:user.uid,email:user.email||'',category:kind,area,message:text.slice(0,4000),diagnostics:diag?diagnostics():null});setDone(true)}catch{setErr(`Piper could not send that right now. Check your connection and try again, or email ${FEEDBACK_EMAIL}.`)}finally{setBusy(false)}}
 const mail=`mailto:${FEEDBACK_EMAIL}?subject=${encodeURIComponent('Piper beta feedback')}&body=${encodeURIComponent(msg.trim()+`\n\n— Piper ${APP_VERSION} (${APP_BUILD}, ${platformName()})`)}`;
 return <div className="modal" role="dialog" aria-modal="true"><div className="modal-card feedback-modal"><div className="modal-head"><div><h2>{done?'Thank you!':'Send feedback'}</h2><p>{done?'Your feedback was sent. It helps make Piper better.':'Found something confusing, broken or brilliant? Tell us.'}</p></div><button aria-label="Close" onClick={close}><X/></button></div>
  {done?<button className="primary wide" onClick={close}>Done</button>:!user?<><p className="feedback-signin">Sign in under <b>Account &amp; Sync</b> so Piper can send your feedback, or email it to us instead.</p><a className="primary wide" href={mail}>Email {FEEDBACK_EMAIL}</a></>:<>
  <label>What kind of feedback?</label><div className="feedback-kinds" role="radiogroup" aria-label="Kind of feedback">{FEEDBACK_KINDS.map(([k,l])=><button key={k} type="button" role="radio" aria-checked={kind===k} className={kind===k?'on':''} onClick={()=>setKind(k)}>{l}</button>)}</div>
  <label htmlFor="fb-area">Where in Piper? <small>(optional)</small></label><select id="fb-area" value={area} onChange={e=>setArea(e.target.value)}><option value="">Choose an area</option>{FEEDBACK_AREAS.map(a=><option key={a}>{a}</option>)}</select>
  <label htmlFor="fb-msg">Tell us what happened</label><textarea id="fb-msg" value={msg} maxLength={4000} onChange={e=>setMsg(e.target.value)} placeholder={kind==='bug'?'What did you tap, what did you expect, and what happened instead?':'Tell us more…'}/>
  <label className="toggle-row feedback-diag"><input type="checkbox" checked={diag} onChange={e=>setDiag(e.target.checked)}/> Include technical details (app version, device type, screen size)</label>
  <small className="feedback-privacy">Your email and these details are sent with your note. Your recipes, lists and pantry are never included.</small>
  {err&&<div className="chef-error" role="alert">{err}</div>}
  <button className="primary wide" disabled={busy||msg.trim().length<3} onClick={()=>void send()}>{busy?<><i className="spin"/>Sending…</>:'Send feedback'}</button></>}
 </div></div>}
type DialogAction={id:string;label:string;kind?:'primary'|'secondary'|'danger'};
type DialogRequest={title:string;message?:string;actions:DialogAction[];resolve:(id:string)=>void};
let dialogHost:((r:DialogRequest)=>void)|null=null;
function askDialog(o:{title:string;message?:string;actions:DialogAction[]}):Promise<string>{return new Promise(resolve=>{if(!dialogHost){const ok=window.confirm(o.title+(o.message?'\n'+o.message:''));resolve(ok?o.actions[0].id:'cancel');return}dialogHost({...o,resolve})})}
function askConfirm(title:string,message:string,confirmLabel='Confirm',danger=false):Promise<boolean>{return askDialog({title,message,actions:[{id:'ok',label:confirmLabel,kind:danger?'danger':'primary'}]}).then(id=>id==='ok')}
function DialogHost(){const[req,setReq]=useState<DialogRequest|null>(null);const box=useRef<HTMLDivElement>(null);const opener=useRef<HTMLElement|null>(null);const cur=useRef<DialogRequest|null>(null);const openedAt=useRef(0);useEffect(()=>{dialogHost=r=>{openedAt.current=Date.now();cur.current?.resolve('cancel');if(!cur.current)opener.current=document.activeElement as HTMLElement|null;cur.current=r;setReq(r)};return()=>{dialogHost=null}},[]);function finish(id:string){const r=cur.current;cur.current=null;setReq(null);r?.resolve(id);setTimeout(()=>opener.current?.focus?.(),0)}useEffect(()=>{if(!req)return;const t=setTimeout(()=>{const cancel=box.current?.querySelector<HTMLElement>('[data-cancel]');cancel?.focus()},30);return()=>clearTimeout(t)},[req]);useEffect(()=>{if(!req)return;function key(e:KeyboardEvent){if(e.key==='Escape'){e.preventDefault();e.stopPropagation();finish('cancel')}if(e.key==='Tab'&&box.current){const f=Array.from(box.current.querySelectorAll<HTMLElement>('button:not(:disabled)'));if(!f.length)return;const first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}document.addEventListener('keydown',key,true);return()=>document.removeEventListener('keydown',key,true)},[req]);if(!req)return null;return <div className="dialog-backdrop" onClick={()=>{if(Date.now()-openedAt.current>400)finish('cancel')}}><div className="dialog-sheet" ref={box} role="alertdialog" aria-modal="true" aria-labelledby="piper-dialog-title" aria-describedby={req.message?'piper-dialog-msg':undefined} onClick={e=>e.stopPropagation()}><h2 id="piper-dialog-title">{req.title}</h2>{req.message&&<p id="piper-dialog-msg">{req.message}</p>}<div className="dialog-actions">{req.actions.map(a=><button key={a.id} className={'dialog-btn '+(a.kind||'secondary')} onClick={()=>finish(a.id)}>{a.label}</button>)}<button className="dialog-btn cancel" data-cancel onClick={()=>finish('cancel')}>Cancel</button></div></div></div>}
/* Pass 22: pressing Enter (or Go/Return on a phone keyboard) in a box moves to the next empty box, or presses the main button. */
const ENTER_TYPES=new Set(['text','email','password','number','url','tel','search','']);
function EnterSubmits(){useEffect(()=>{function key(e:KeyboardEvent){if(e.key!=='Enter'||e.defaultPrevented||e.isComposing||e.shiftKey||e.altKey||e.metaKey||e.ctrlKey)return;const el=e.target as HTMLElement|null;if(!el||el.tagName!=='INPUT')return;const inp=el as HTMLInputElement;if(!ENTER_TYPES.has((inp.getAttribute('type')||'').toLowerCase()))return;
 const compact=inp.closest('.inline-add.compact');if(compact){const b=compact.querySelector<HTMLButtonElement>('button:not(:disabled)');if(b){e.preventDefault();b.click()}return}
 if(inp.closest('.inline-add,.search,.chef-refine-row'))return;
 const box=inp.closest<HTMLElement>('.modal-card,.welcome-card');if(!box)return;
 const visible=(x:HTMLElement)=>!!(x.offsetWidth||x.offsetHeight||x.getClientRects().length);
 const fields=Array.from(box.querySelectorAll<HTMLInputElement|HTMLTextAreaElement>('input,textarea')).filter(f=>visible(f)&&!f.disabled&&!f.hidden&&(f.tagName==='TEXTAREA'||ENTER_TYPES.has((f.getAttribute('type')||'').toLowerCase())));
 const next=fields.slice(fields.indexOf(inp)+1).find(f=>!f.value);
 e.preventDefault();
 if(next){next.focus();return}
 const btn=Array.from(box.querySelectorAll<HTMLButtonElement>('button.primary')).find(b=>!b.disabled&&visible(b));
 if(btn){inp.blur();btn.click()}}
 document.addEventListener('keydown',key);return()=>document.removeEventListener('keydown',key)},[]);return null}
function EscapeCloses(){useEffect(()=>{function key(e:KeyboardEvent){if(e.key!=='Escape'||e.defaultPrevented)return;const modals=document.querySelectorAll('.modal');const top=modals[modals.length-1];const btn=top?.querySelector<HTMLElement>('button[aria-label="Close"]');if(btn){e.preventDefault();btn.click()}}document.addEventListener('keydown',key);return()=>document.removeEventListener('keydown',key)},[]);return null}
function Photo({src,alt='',className,fallback}:{src?:string;alt?:string;className?:string;fallback?:React.ReactNode}){const[failed,setFailed]=useState(false);const[loaded,setLoaded]=useState(false);const img=useRef<HTMLImageElement>(null);useEffect(()=>{setFailed(false);setLoaded(false)},[src]);useEffect(()=>{const el=img.current;if(el&&el.complete&&el.naturalWidth>0)setLoaded(true)},[src,failed]);if(!src||failed)return<>{fallback??<div className="img-fallback-box"><ImageIcon/></div>}</>;return<img ref={img} src={src} alt={alt} className={(className?className+' ':'')+'photo-img'+(loaded?' loaded':'')} loading="lazy" onLoad={()=>setLoaded(true)} onError={()=>setFailed(true)}/>}
function Brand({compact=false}:{compact?:boolean}){return <img className="brand-logo" src={`${import.meta.env.BASE_URL}assets/piper-logo.png`} alt="Piper - Good food, made easier." style={{display:'block',width:compact?'158px':'235px',height:compact?'52px':'78px',maxWidth:'55vw',objectFit:'contain',objectPosition:'left center'}}/>}
function AppHeader({prefs,profile}:{prefs:Prefs;profile:()=>void}){const[compact,setCompact]=useState(false);useEffect(()=>{const on=()=>{const y=window.scrollY||0;setCompact(c=>c?y>12:y>90)};on();window.addEventListener('scroll',on,{passive:true});return()=>window.removeEventListener('scroll',on)},[]);return <header className={compact?'compact':''}><Brand compact={compact}/><button className="avatar" onClick={profile} aria-label="Open preferences">{prefs.photo?<img className="header-profile-photo" src={prefs.photo} alt=""/>:<UserRound/>}</button></header>}
function Nav({page,set,feedbackNew=0}:{page:Page;set:(p:Page)=>void;feedbackNew?:number}){const data:[[Page,React.ReactNode,string],...[Page,React.ReactNode,string][]]=[['recipes',<Home/>,'Recipes'],['planner',<CalendarDays/>,'Planner'],['grocery',<ShoppingCart/>,'Grocery'],['pantry',<Package/>,'Pantry'],['discover',<Compass/>,'Discover'],['prefs',<Settings/>,'Prefs']];return <nav aria-label="Main">{data.map(([p,i,l])=><button key={p} className={page===p?'active':''} aria-current={page===p?'page':undefined} onClick={()=>set(p)}>{i}<span>{l}</span>{p==='prefs'&&feedbackNew>0&&<em className="nav-feedback-badge" aria-label={`${feedbackNew} new feedback report${feedbackNew===1?'':'s'}`}>{feedbackNew>9?'9+':feedbackNew}</em>}</button>)}</nav>}
type SharedFrom={uid:string;name:string;label:string};
type FamilyView={members:FamilyMember[];me:string;mine:Recipe[];open:(r:Recipe,from:SharedFrom)=>void;openMine:(r:Recipe)=>void};
function Recipes({recipes,family,archived=0,openArchive,prefs,open,fav,add}:{recipes:Recipe[];family?:FamilyView;archived?:number;openArchive?:()=>void;prefs:Prefs;open:(r:Recipe)=>void;fav:(id:string)=>void;add:()=>void}){const[tab,setTab]=useState<'mine'|'family'>('mine');const familyTabs=family&&<div className="family-tabs" role="tablist" aria-label="Whose recipes"><button role="tab" aria-selected={tab==='mine'} className={tab==='mine'?'on':''} onClick={()=>setTab('mine')}>My recipes</button><button role="tab" aria-selected={tab==='family'} className={tab==='family'?'on':''} onClick={()=>setTab('family')}>👨‍👩‍👧 Family recipes</button></div>;const archiveNote=archived>0&&<button type="button" className="archive-note" onClick={openArchive}><Package/><span><b>{archived} recipe{archived===1?' is':'s are'} in your Pro archive</b><small>Swap which {FREE_RECIPE_LIMIT} are active, or upgrade to bring them all back.</small></span></button>;const[q,setQ]=useState('');const[category,setCategory]=useState('All');const[view,setView]=useState<'home'|'favorites'|'all'>('home');const favorites=recipes.filter(r=>r.favorite);const others=recipes.filter(r=>!r.favorite);const matches=(r:Recipe)=>{const search=(r.title+' '+r.tags.join(' ')+' '+r.ingredients.join(' ')).toLowerCase().includes(q.toLowerCase());const cat=category==='All'||r.tags.some(t=>t.toLowerCase()===category.toLowerCase())||r.title.toLowerCase().includes(category.toLowerCase())||r.ingredients.some(i=>i.toLowerCase().includes(category.toLowerCase()));return search&&cat};const list=(view==='favorites'?favorites:recipes).filter(matches);if(family&&tab==='family')return <section><div className="page-title"><div><h1>Family Recipes</h1><p>Recipes shared by everyone in your Piper Family. Open one to save it to your own recipe box.</p></div></div>{familyTabs}<FamilyRecipes family={family} prefs={prefs}/></section>;if(view!=='home')return <section><div className="page-title"><div><button className="text-link recipe-back" onClick={()=>setView('home')}>← My Recipes</button><h1>{view==='favorites'?'All Favorites':'All Recipes'}</h1><p>{list.length} recipe{list.length===1?'':'s'}</p></div></div><RecipeCategoryBar category={category} setCategory={setCategory}/><div className="recipe-grid">{list.map(r=><RecipeCard key={r.id} r={r} prefs={prefs} open={()=>open(r)} fav={()=>fav(r.id)}/>)}</div></section>;return <section><div className="page-title"><div><h1>{prefs.name?`${prefs.name}'s Recipes`:'My Recipes'}</h1><p>Your recipe box. Paste a web link, a caption or a photo of a recipe card to add it.</p></div><button className="primary" onClick={add}><Plus/>Add recipe</button></div>{familyTabs}{archiveNote}<div className="search"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search recipes..." aria-label="Search recipes"/></div><RecipeCategoryBar category={category} setCategory={setCategory}/><div className="section-head"><div><h2>Favorites</h2><p>Your go-to recipes, right up front.</p></div><button className="text-link" onClick={()=>setView('favorites')}>View all</button></div><div className="recipe-grid favorites-row">{favorites.filter(matches).slice(0,3).map(r=><RecipeCard key={r.id} r={r} prefs={prefs} open={()=>open(r)} fav={()=>fav(r.id)}/>)}</div><div className="section-head"><div><h2>All Recipes</h2><p>Everything else in your recipe box.</p></div><button className="text-link" onClick={()=>setView('all')}>View all</button></div><div className="recipe-grid">{others.filter(matches).slice(0,6).map(r=><RecipeCard key={r.id} r={r} prefs={prefs} open={()=>open(r)} fav={()=>fav(r.id)}/>)}</div></section>}
function FamilyRecipes({family,prefs}:{family:FamilyView;prefs:Prefs}){const[list,setList]=useState<FamilyRecipe<Recipe>[]|null>(null);const[err,setErr]=useState('');const[q,setQ]=useState('');const[who,setWho]=useState('all');const others=family.members.filter(m=>m.uid!==family.me);const key=others.map(m=>m.uid).join(',');async function load(){setErr('');setList(null);try{setList(await loadFamilyRecipes<Recipe>(family.members,family.me))}catch{setErr('Piper could not load your family’s recipes. Check your connection and try again.');setList([])}}useEffect(()=>{if(others.length)void load()},[key]);const view=useMemo(()=>dedupeFamily<Recipe>(list||[],family.mine,family.me),[list,family.mine,family.me]);if(!others.length)return <div className="grocery-empty"><Home/><h2>No one else is here yet</h2><p>Invite your family from Prefs → Your plan. Their recipes will show up here.</p></div>;const shown=view.cards.filter(c=>(who==='all'||c.owners.some(o=>o.uid===who))&&(c.recipe.title+' '+c.recipe.ingredients.join(' ')).toLowerCase().includes(q.toLowerCase()));const chip=(c:typeof view.cards[number])=>c.versionOf?`${c.owners[0].name}’s version`:`From ${ownersLabel(c.owners)}`;const label=(c:typeof view.cards[number])=>c.versionOf?`${c.owners[0].name}’s version of ${c.versionOf} recipe`:`From ${ownersLabel(c.owners)}’s recipes`;return <>{others.length>1&&<div className="recipe-category-wrap"><div className="recipe-category-bar"><button className={who==='all'?'active':''} onClick={()=>setWho('all')}>Everyone</button>{others.map(m=><button key={m.uid} className={who===m.uid?'active':''} onClick={()=>setWho(m.uid)}>{m.name}</button>)}</div></div>}<div className="search"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search family recipes..." aria-label="Search family recipes"/></div>{err&&<div className="chef-error" role="alert">{err}</div>}{list===null?<p className="family-loading" role="status"><i className="spin"/>Loading family recipes…</p>:!shown.length?<div className="grocery-empty"><Home/><h2>{view.cards.length?'No matches':'Nothing shared yet'}</h2><p>{view.cards.length?'Try a different search.':'When family members save recipes, they show up here. Recipes marked private stay hidden.'}</p></div>:<div className="recipe-grid">{shown.map(c=><RecipeCard key={c.key} r={c.recipe} prefs={prefs} from={chip(c)} saved={!!c.saved} open={()=>c.saved?family.openMine(c.saved):family.open(c.recipe,{uid:c.owners[0].uid,name:c.owners[0].name,label:label(c)})} fav={()=>{}}/>)}</div>}{list!==null&&(view.hiddenCopies>0||view.merged>0)&&<p className="family-dedupe-note">{[view.hiddenCopies?`${view.hiddenCopies} saved ${view.hiddenCopies===1?'copy':'copies'} hidden`:'',view.merged?`${view.merged} matching ${view.merged===1?'recipe':'recipes'} combined`:''].filter(Boolean).join(' · ')} so nothing shows twice.</p>}{list!==null&&<button className="secondary family-refresh" onClick={()=>void load()}>Refresh family recipes</button>}</>}
function RecipeCategoryBar({category,setCategory}:{category:string;setCategory:(x:string)=>void}){return <div className="recipe-category-wrap"><div className="recipe-category-bar"><button className={category==='All'?'active':''} onClick={()=>setCategory('All')}>All</button>{RECIPE_CATEGORIES.map(c=><button key={c} className={category===c?'active':''} onClick={()=>setCategory(c)}>{c}</button>)}</div></div>}

function RecipeCard({r,prefs,open,fav,from,saved}:{r:Recipe;prefs:Prefs;open:()=>void;fav:()=>void;from?:string;saved?:boolean}){const w=warnings(r,prefs);return <article className="recipe-card" tabIndex={0} aria-label={`${r.title}, ${r.time} minutes. Open recipe`} onClick={open} onKeyDown={e=>{if(e.target===e.currentTarget&&(e.key==='Enter'||e.key===' ')){e.preventDefault();open()}}}><div className="photo">{r.image?<Photo src={r.image} alt={r.title} fallback={<div className="recipe-photo-placeholder">Photo unavailable</div>}/>:<div className="recipe-photo-placeholder">{r.sourceName===CHEF_NAME&&!r.sourceUrl?'Created by Piper’s Chef':'Photo stored on importing device'}</div>}{saved&&<span className="saved-chip" aria-label="Already in your recipes"><Check/>Saved</span>}{!from&&<button className="card-share" aria-label={`Share ${r.title}`} onClick={e=>{e.stopPropagation();void shareRecipe(r)}}><Share2/></button>}{from?<span className="from-chip">{from}</span>:<button className="heart" aria-label={r.favorite?`Remove ${r.title} from favorites`:`Add ${r.title} to favorites`} aria-pressed={!!r.favorite} onClick={e=>{e.stopPropagation();fav()}}><Heart className={r.favorite?'filled':''}/></button>}</div><div className="recipe-body"><h3>{r.title}</h3><p>{r.time} min · {r.servings} servings</p>{w.filter(x=>x.startsWith('Allergy')).map(x=><div key={x} className="warn allergy-badge"><AlertTriangle/>{x}</div>)}{w.filter(x=>x.startsWith('Avoid')).map(x=><div key={x} className="warn avoid-badge"><AlertTriangle/>{x}</div>)}</div></article>}
function RecipeDetail({recipe,prefs,shared,family,togglePrivate,close,favorite,edit,cook,addToPlanner,deleteRecipe,addGroceries}:{recipe:Recipe;prefs:Prefs;shared?:{from:string;copy:()=>void};family?:boolean;togglePrivate?:()=>void;close:()=>void;favorite:()=>void;edit:()=>void;cook:(scale:number)=>void;addToPlanner:(day:string,meal:string)=>void;deleteRecipe:()=>void;addGroceries:(scale:number)=>{added:number;skipped:number}}){const[scale,setScale]=useState(1);const[addedMsg,setAddedMsg]=useState('');const[plannerOpen,setPlannerOpen]=useState(false);const[planDay,setPlanDay]=useState('Mon');const[planMeal,setPlanMeal]=useState('Dinner');const w=warnings(recipe,prefs);return <div className="detail"><div className="hero"><Photo src={recipe.image} alt={recipe.title} fallback={<div className="hero-fallback"><ImageIcon/></div>}/><button className="round left" aria-label="Back" onClick={close}><ArrowLeft/></button>{!shared&&<div className="hero-actions"><button className="round" aria-label={recipe.favorite?'Remove from favorites':'Add to favorites'} aria-pressed={!!recipe.favorite} onClick={favorite}><Heart className={recipe.favorite?'filled':''}/></button><button className="round" aria-label="Share recipe" onClick={()=>void shareRecipe(recipe,scale)}><Share2/></button><button className="round" aria-label="Edit recipe" onClick={edit}><Edit3/></button></div>}</div><div className="content"><h1>{recipe.title}</h1><p>{recipe.time} minutes · Base recipe serves {recipe.servings}</p>{shared&&<div className="family-from"><span>{shared.from}</span><button className="primary" onClick={shared.copy}><Plus/>Save to my recipes</button></div>}{!shared&&recipe.copiedFrom&&<small className="copied-note">📥 Saved from {recipe.copiedFrom.name}’s recipes{isUneditedCopy(recipe)?' · your family sees just the original, so it won’t show twice':' · you’ve edited it, so your family sees it as your version'}</small>}{!shared&&family&&togglePrivate&&<button type="button" className={'share-toggle'+(recipe.familyPrivate?' off':'')} aria-pressed={!recipe.familyPrivate} onClick={togglePrivate}><span>{recipe.familyPrivate?'🔒 Private: hidden from your family':'👨‍👩‍👧 Shared with your family'}</span><small>Tap to {recipe.familyPrivate?'share it':'make it private'}</small></button>}{(!!recipe.madeCount||!!recipe.rating)&&<p className="made-line">{!!recipe.rating&&<span className="made-stars" aria-label={`Rated ${recipe.rating} out of 5`}>{'★'.repeat(recipe.rating||0)}{'☆'.repeat(5-(recipe.rating||0))}</span>}{!!recipe.madeCount&&<span>Made {recipe.madeCount} time{recipe.madeCount===1?'':'s'}{recipe.lastMade?` · last on ${new Date(recipe.lastMade).toLocaleDateString(undefined,{month:'short',day:'numeric'})}`:''}</span>}</p>}{w.filter(x=>x.startsWith('Allergy')).map(x=><div key={x} className="callout allergy-badge"><AlertTriangle/><div><b>Allergy warning</b><br/>{x.replace('Allergy: ','')}</div></div>)}{w.filter(x=>x.startsWith('Avoid')).map(x=><div key={x} className="callout avoid-badge"><AlertTriangle/><div><b>Avoid ingredient</b><br/>{x.replace('Avoid: ','')}</div></div>)}<div className="scales">{[.5,1,2,3,4].map(n=><button key={n} className={scale===n?'active':''} onClick={()=>setScale(n)}>{n===.5?'½':n}×</button>)}</div><div className="action-row"><button className="primary wide" onClick={()=>cook(scale)}>Make Recipe{scale!==1?` (${scale===.5?'½':scale}×)`:''}</button><button className="secondary wide" aria-live="polite" onClick={()=>{const r=addGroceries(scale);setAddedMsg(r.added?`✓ Added ${r.added} item${r.added===1?'':'s'}${scale!==1?' ('+(scale===.5?'½':scale)+'×)':''}`:'✓ Already on your list');setTimeout(()=>setAddedMsg(''),2600)}}>{addedMsg||'Add ingredients to grocery'}</button></div><button className="planner-use-btn" onClick={()=>setPlannerOpen(true)}><CalendarDays/>{shared?'Save & use in Planner':'Use in Planner'}</button>{plannerOpen&&<div className="modal" role="dialog" aria-modal="true"><div className="modal-card planner-use-modal"><div className="modal-head"><div><h2>Use in Planner</h2><p>{recipe.title}</p></div><button aria-label="Close" onClick={()=>setPlannerOpen(false)}><X/></button></div><label>Day</label><select value={planDay} onChange={e=>setPlanDay(e.target.value)}>{['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=><option key={d}>{d}</option>)}</select><label>Meal</label><select value={planMeal} onChange={e=>setPlanMeal(e.target.value)}>{['Breakfast','Lunch','Dinner'].map(m=><option key={m}>{m}</option>)}</select><button className="primary wide" onClick={()=>{addToPlanner(planDay,planMeal);setPlannerOpen(false)}}>Add to {planDay} {planMeal}</button></div></div>}<h2>Ingredients</h2><ul className="ingredients">{recipe.ingredients.map((x,i)=><li key={i}>{scaleIngredient(x,scale)}</li>)}</ul><h2>Instructions</h2><ol className="instructions">{recipe.instructions.map((x,i)=><li key={i}><b>{i+1}</b><span>{x}</span></li>)}</ol>{!!recipe.notes?.trim()&&<><h2>Your notes</h2><div className="recipe-notes">{recipe.notes}</div></>}{!shared&&<div className="recipe-danger-zone"><button className="delete-recipe" onClick={()=>{void askConfirm('Delete this recipe?',`${recipe.title} will be removed from My Recipes and your Planner.`,'Delete recipe',true).then(ok=>{if(ok)deleteRecipe()})}}><Trash2/>Delete Recipe</button></div>}</div></div>}
type CookTimer={id:string;label:string;total:number;end:number;fired:boolean;key:string};
function fmtDur(sec:number){const h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60),x=sec%60;return[h?`${h} hr`:'',m?`${m} min`:'',x&&!h?`${x} sec`:''].filter(Boolean).join(' ')}
function fmtClock(sec:number){const h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60),x=sec%60,pad=(n:number)=>String(n).padStart(2,'0');return h?`${h}:${pad(m)}:${pad(x)}`:`${m}:${pad(x)}`}
function parseTimers(text:string){const out:{seconds:number;range:string}[]=[];const N='(\\d+(?:\\.\\d+)?(?:\\s+\\d+\\/\\d+|\\s?[¼½¾])?|[¼½¾])';const re=new RegExp('(^|[^\\d/.])'+N+'(?:\\s*(?:-|–|—|to|or)\\s*'+N+')?\\s*(hours?|hrs?|minutes?|mins?|seconds?|secs?)\\b','gi');let m:RegExpExecArray|null;while((m=re.exec(text))&&out.length<3){const unit=m[4].toLowerCase(),mult=unit[0]==='h'?3600:unit[0]==='m'?60:1;const qty=parseQty(m[2]);if(!isFinite(qty))continue;const seconds=Math.round(qty*mult);if(seconds<5||seconds>43200||out.some(o=>o.seconds===seconds))continue;const word=unit[0]==='h'?'hr':unit[0]==='m'?'min':'sec';out.push({seconds,range:m[3]?`${m[2]}–${m[3]} ${word}`:''})}return out}
const GENERIC_LAST=new Set(['pepper','sauce','powder','juice','paste','oil','seeds','leaves','cheese','water','vinegar']);
const CUT_WORDS=new Set(['breast','breasts','thigh','thighs','wing','wings','drumstick','drumsticks','fillet','fillets','filet','tenderloin','tenderloins','steak','steaks','chop','chops','roast','loin']);
function stepIngredients(step:string,ingredients:string[]){const hay=' '+step.toLowerCase().replace(/[^a-z0-9\s-]/g,' ')+' ';const found:string[]=[];const has=(t:string)=>{const base=t.replace(/(es|s)$/,'');return[t,base].filter(v=>v.length>2).some(v=>new RegExp(`\\s${v.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}(?:s|es)?\\s`).test(hay))};ingredients.forEach(ing=>{const name=cleanIngredient(ing).replace(/[^a-z\s-]/g,' ').replace(/\s+/g,' ').trim();if(!name)return;const words=name.split(' ');const last=words[words.length-1],last2=words.slice(-2).join(' ');const head=last.length>=4&&!GENERIC_LAST.has(last)&&has(last);const cut=words.length>1&&CUT_WORDS.has(last)&&has(words[words.length-2]);if((has(name)||(words.length>1&&has(last2))||head||cut)&&!found.includes(ing))found.push(ing)});return found.slice(0,6)}
function Cook({recipe,scale,close,finish}:{recipe:Recipe;scale:number;close:()=>void;finish:(patch:{madeCount:number;lastMade:number;rating?:number;notes?:string})=>void}){
 const steps=recipe.instructions.length?recipe.instructions:['No steps have been added to this recipe yet.'];
 const total=steps.length;
 const[step,setStep]=useState(0);
 const[drawer,setDrawer]=useState(false);
 const[done,setDone]=useState(false);
 const[checked,setChecked]=useState<Record<number,boolean>>({});
 const[timers,setTimers]=useState<CookTimer[]>([]);
 const[now,setNow]=useState(Date.now());
 const[textSize,setTextSize]=useState<number>(()=>{try{const v=Number(localStorage.getItem('piper.cook.text'));return v>=0&&v<=2&&localStorage.getItem('piper.cook.text')!==null?v:1}catch{return 1}});
 const[rating,setRating]=useState(0);
 const[note,setNote]=useState('');
 const touch=useRef(0),lock=useRef<any>(null),audio=useRef<AudioContext|null>(null);
 const scaleText=scale===.5?'½':String(scale);
 useEffect(()=>{let alive=true;async function get(){try{if(alive&&document.visibilityState==='visible')lock.current=await(navigator as any).wakeLock?.request('screen')}catch{}}void get();const vis=()=>{if(document.visibilityState==='visible')void get()};document.addEventListener('visibilitychange',vis);return()=>{alive=false;document.removeEventListener('visibilitychange',vis);lock.current?.release?.()}},[]);
 useEffect(()=>{if(!timers.length)return;const t=setInterval(()=>setNow(Date.now()),500);return()=>clearInterval(t)},[timers.length]);
 function beep(){const ctx=audio.current;if(ctx){try{[0,.28,.56].forEach(d=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=880;o.connect(g);g.connect(ctx.destination);const t=ctx.currentTime+d;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.35,t+.02);g.gain.exponentialRampToValueAtTime(.0001,t+.22);o.start(t);o.stop(t+.25)})}catch{}}try{navigator.vibrate?.([300,150,300])}catch{}}
 useEffect(()=>{const due=timers.filter(t=>!t.fired&&t.end<=now);if(!due.length)return;setTimers(ts=>ts.map(t=>due.some(d=>d.id===t.id)?{...t,fired:true}:t));beep()},[now,timers]);
 const ringing=timers.some(t=>t.fired);
 useEffect(()=>{if(!ringing)return;const i=setInterval(beep,6000);return()=>clearInterval(i)},[ringing]);
 function startTimer(seconds:number,key:string){try{audio.current=audio.current||new(window.AudioContext||(window as any).webkitAudioContext)();void audio.current.resume?.()}catch{}const t=Date.now();setNow(t);setTimers(ts=>[...ts,{id:crypto.randomUUID(),label:`Step ${step+1} · ${fmtDur(seconds)}`,total:seconds,end:t+seconds*1000,fired:false,key}])}
 function move(n:number){setStep(s=>Math.max(0,Math.min(total-1,s+n)))}
 function next(){if(step>=total-1)setDone(true);else move(1)}
 async function requestExit(){const live=timers.some(t=>!t.fired);if(!live&&step===0){close();return}const ok=await askConfirm('Leave cook mode?',live?'Your running timers will stop.':'You can start again any time from the recipe.','Leave',true);if(ok)close()}
 useEffect(()=>{function key(e:KeyboardEvent){if(document.querySelector('.dialog-backdrop'))return;const tag=(e.target as HTMLElement)?.tagName;if(tag==='TEXTAREA'||tag==='INPUT')return;if(e.key==='Escape'){if(drawer)setDrawer(false);else if(!done)void requestExit()}else if(!drawer&&!done){if(e.key==='ArrowRight'){e.preventDefault();next()}if(e.key==='ArrowLeft'){e.preventDefault();move(-1)}}}document.addEventListener('keydown',key);return()=>document.removeEventListener('keydown',key)});
 function setSize(n:number){setTextSize(n);try{localStorage.setItem('piper.cook.text',String(n))}catch{}}
 function save(){const stamp=new Date().toLocaleDateString(undefined,{month:'short',day:'numeric'});const cleaned=note.trim();finish({madeCount:(recipe.madeCount||0)+1,lastMade:Date.now(),rating:rating||recipe.rating,notes:cleaned?`${recipe.notes?recipe.notes.trim()+'\n':''}${stamp}: ${cleaned}`:recipe.notes})}
 if(done)return <div className="cook cook-done"><div className="cook-done-card"><div className="cook-done-icon"><Check/></div><h1>Nicely done!</h1><p>{recipe.title} is ready to enjoy.</p><div className="cook-rate" role="radiogroup" aria-label="Rate this recipe">{[1,2,3,4,5].map(n=><button key={n} role="radio" aria-checked={rating===n} aria-label={`${n} star${n>1?'s':''}`} className={n<=rating?'on':''} onClick={()=>setRating(r=>r===n?0:n)}>★</button>)}</div><label htmlFor="cook-note">Anything you would change next time?</label><textarea id="cook-note" value={note} onChange={e=>setNote(e.target.value)} placeholder="Optional, e.g. less salt, bake 5 minutes longer"/><button className="primary wide" onClick={save}>Save and finish</button><button className="cook-skip" onClick={close}>Skip</button></div></div>;
 const opts=parseTimers(steps[step]);
 const here=recipe.instructions.length?stepIngredients(steps[step],recipe.ingredients).map(x=>scaleIngredient(x,scale)):[];
 const checkedCount=Object.values(checked).filter(Boolean).length;
 return <div className="cook" onTouchStart={e=>{touch.current=e.touches[0].clientX}} onTouchEnd={e=>{const d=e.changedTouches[0].clientX-touch.current;if(Math.abs(d)>60)move(d<0?1:-1)}}>
  <div className="cook-top"><button onClick={()=>void requestExit()} aria-label="Exit cook mode"><X/> Exit</button><span className="cook-count">{step+1} of {total}{scale!==1&&<em>{scaleText}×</em>}</span><button className="cook-ing-btn" onClick={()=>setDrawer(true)}><ListChecks/>Ingredients{checkedCount>0&&<b>{checkedCount}/{recipe.ingredients.length}</b>}</button></div>
  <div className="cook-progress" role="progressbar" aria-label="Recipe progress" aria-valuemin={1} aria-valuemax={total} aria-valuenow={step+1}><i style={{width:`${((step+1)/total)*100}%`}}/></div>
  <div className="cook-stage"><div className="cook-card" key={step} data-size={textSize}>
   <div className="cook-card-head"><small>STEP {step+1}</small><div className="cook-size"><button aria-label="Smaller text" disabled={textSize===0} onClick={()=>setSize(textSize-1)}>A−</button><button aria-label="Larger text" disabled={textSize===2} onClick={()=>setSize(textSize+1)}>A+</button></div></div>
   <p>{steps[step]}</p>
   {opts.length>0&&<div className="cook-suggest">{opts.map(o=>{const key=`${step}:${o.seconds}`;const running=timers.some(t=>t.key===key&&!t.fired);return <button key={key} disabled={running} onClick={()=>startTimer(o.seconds,key)}><TimerIcon/>{running?'Timer running':`Start ${fmtDur(o.seconds)} timer`}{!running&&o.range&&<span>({o.range})</span>}</button>})}</div>}
   {here.length>0&&<div className="cook-step-ing"><b>This step uses</b><div>{here.map(x=><span key={x}>{x}</span>)}</div></div>}
  </div></div>
  {timers.length>0&&<div className="cook-timer-tray" role="region" aria-label="Timers" onTouchStart={e=>e.stopPropagation()} onTouchEnd={e=>e.stopPropagation()}>{timers.map(t=>{const left=Math.max(0,Math.ceil((t.end-now)/1000));return <div key={t.id} role={t.fired?'alert':undefined} className={'cook-timer'+(t.fired?' ringing':'')}><div className="cook-timer-main">{t.fired?<BellRing/>:<TimerIcon/>}<div><b>{t.fired?'Time is up':fmtClock(left)}</b><small>{t.label}</small></div></div><div className="cook-timer-actions">{!t.fired&&<button aria-label="Add one minute" onClick={()=>setTimers(ts=>ts.map(x=>x.id===t.id?{...x,end:x.end+60000,total:x.total+60}:x))}>+1 min</button>}<button aria-label={t.fired?'Dismiss timer':'Cancel timer'} onClick={()=>setTimers(ts=>ts.filter(x=>x.id!==t.id))}>{t.fired?'Dismiss':<X/>}</button></div>{!t.fired&&<i style={{width:`${Math.min(100,(left/t.total)*100)}%`}}/>}</div>})}</div>}
  <div className="cook-nav"><button disabled={!step} onClick={()=>move(-1)}><ChevronLeft/>Previous</button><button className={step>=total-1?'finish':''} onClick={next}>{step>=total-1?<>Finish<Check/></>:<>Next<ChevronRight/></>}</button></div>
  {drawer&&<div className="cook-drawer-backdrop" onClick={()=>setDrawer(false)} onTouchStart={e=>e.stopPropagation()} onTouchEnd={e=>e.stopPropagation()}><div className="cook-drawer" role="dialog" aria-modal="true" aria-label="Ingredients" onClick={e=>e.stopPropagation()}><div className="cook-drawer-head"><div><h2>Ingredients</h2><p>{scale!==1?`Scaled to ${scaleText}× · makes ${Math.round(recipe.servings*scale*100)/100} servings`:`Serves ${recipe.servings}`}</p></div><button aria-label="Close ingredients" onClick={()=>setDrawer(false)}><X/></button></div><ul>{recipe.ingredients.map((x,i)=><li key={i}><button className={checked[i]?'on':''} aria-pressed={!!checked[i]} onClick={()=>setChecked(c=>({...c,[i]:!c[i]}))}><span className="box">{checked[i]&&<Check/>}</span><span>{scaleIngredient(x,scale)}</span></button></li>)}</ul></div></div>}
 </div>}
/* ===== Auto Fill engine: understands what a recipe IS before deciding where it fits ===== */
type AFKind='meal'|'dessert'|'drink'|'snack'|'condiment'|'side';
type AFProfile={r:Recipe;title:string;tags:string;all:string;ing:string;names:string[];kind:AFKind;main:string;veg:boolean;b:boolean;lo:boolean;fx:boolean;dn:boolean;protein?:number|null};
type AFFit={ok:boolean;score:number;soft?:boolean};
const afW=(s:string)=>new RegExp('\\b(?:'+s+')\\b','i');
const afCount=(re:RegExp,s:string)=>{const g=new RegExp(re.source,'gi');const seen=new Set<string>();let m:RegExpExecArray|null;while((m=g.exec(s)))seen.add(m[0].toLowerCase());return seen.size};
const AF_VEGFIX=/\b(black bean|bean|veggie|vegetarian|vegan|lentil|chickpea|falafel|portobello|mushroom|quinoa|tofu|plant[- ]based|turkey|chicken|salmon|tuna|coconut)(\s+)(burgers?|patties|sliders?|meatballs?|meatloaf|sausages?|hot dogs?|bacon|jerky|nuggets?)\b/gi;
