/* --- what kind of thing is it? (judged from the title and tags, never from the ingredient list) --- */
const AF_DESSERT=afW("cakes?|cupcakes?|cookies?|brownies?|blondies|cheesecakes?|candy|candies|fudge|frosting|icing|desserts?|puddings?|ice cream|sorbet|gelato|tarts?|cobblers?|crumbles?|crisps?|donuts?|doughnuts?|truffles?|macarons?|meringues?|pavlova|tiramisu|popsicles?|brittle|caramels?|s'mores|eclairs?|banana bread|pumpkin bread|zucchini bread|sweet rolls?|cinnamon rolls?|pies?");
const AF_SAVORY=/\b(?:crab|fish|salmon|tuna|potato|chicken|rice|corn|zucchini|lentil|bean|veggie|vegetable|cauliflower|shrimp|pork|turkey|beef|meat)\s+(?:cakes?|patties)\b|\bpot pies?\b|\b(?:shepherd'?s|cottage|meat|pork|steak|chicken|turkey|beef|fish|tamale|pizza|cheese|spinach)\s+pies?\b|\b(?:tomato|onion|spinach|leek|cheese|egg|mushroom|veggie)\s+tarts?\b|\bsavory\b|\bbreakfast\b/i;
const AF_DRINK=afW("smoothies?|cocktails?|margaritas?|lemonade|latte|milkshakes?|sangria|mojito|punch|mocktails?|beverages?|frappe|slushies?|hot chocolate|eggnog|kombucha|spritzer|sodas?");
const AF_SNACK=afW("appetizers?|snacks?|hors d'oeuvres?|trail mix|energy (?:balls|bites)|party mix|finger foods?|dips?|bark|granola bars?|protein bars?");
const AF_COND=afW("sauces?|dressings?|marinades?|rubs?|seasoning|spice mix|salsa|guacamole|hummus|jam|jelly|syrup|gravy|glaze|pesto|vinaigrette|aioli|chutney|spreads?|relish|brine|ketchup|mayo|mayonnaise|stock|broth|compote|coulis|creamer");
const AF_MAINW=afW("chicken|turkey|beef|steaks?|pork|bacon|ham|sausages?|lamb|veal|duck|salmon|tuna|fish|shrimp|crab|lobster|scallops?|pasta|spaghetti|noodles?|rice|tacos?|burritos?|enchiladas?|quesadillas?|casserole|lasagna|pizza|stew|chili|soups?|curry|stir[- ]?fry|bowls?|sandwich(?:es)?|burgers?|wraps?|salads?|skillet|bake|roast|ziti|penne|fettuccine|macaroni|mac|risotto|pot pie|dumplings|eggs?|omelets?|frittatas?|quiche|fajitas?|kabobs?|kebabs?|skewers|souvlaki|gyros?|meatballs?|meatloaf|ribs|nachos|tenders?|nuggets?|pancakes?|waffles?|toast|oatmeal|oats|hash|breakfast|tofu");
const AF_SIDE=afW("sides?|side dish|coleslaw|slaw|mashed potatoes|garlic bread|cornbread|dinner rolls?|stuffing|rice pilaf|roasted (?:broccoli|brussels sprouts|carrots|asparagus|potatoes|vegetables|cauliflower|green beans|sweet potatoes)|green beans|fries|french fries|baked beans|breadsticks|brussels sprouts|macaroni salad|potato salad");
const AF_COND_END=/\b(?:sauces?|dressings?|marinades?|gravy|glaze|rub|salsa|dip|spread|seasoning|jam|jelly|syrup|relish|pesto|vinaigrette|aioli|chutney|stock|broth)\s*$/i;
function afKind(title:string,all:string):AFKind{const main=AF_MAINW.test(title)&&!(AF_COND_END.test(title.trim())&&!/\b(?:and|with|in|over|on|&)\b/.test(title));if(AF_DESSERT.test(all)&&!AF_SAVORY.test(all))return'dessert';if(AF_DRINK.test(all)&&!/\bbowl\b/.test(all))return'drink';if(AF_SNACK.test(all))return'snack';if(AF_COND.test(title)&&!main)return'condiment';if(AF_SIDE.test(all)&&!main)return'side';return'meal'}

/* --- main protein (used for variety and for diet checks) --- */
const AF_PROT:[string,RegExp][]=[['chicken',afW("chicken")],['turkey',afW("turkey")],['beef',afW("beef|steaks?|brisket|burgers?|hamburgers?|cheeseburgers?|meatballs?|meatloaf|flank|sirloin|ribeye|chuck|sloppy joes?")],['pork',afW("pork|bacon|ham|sausages?|chorizo|pepperoni|salami|prosciutto|pancetta|ribs|hot dogs?|bratwurst|carnitas")],['lamb',afW("lamb")],['fish',afW("salmon|tuna|cod|tilapia|trout|halibut|mahi|catfish|snapper|bass|haddock|sardines?|anchov(?:y|ies)|swordfish|fish|seafood")],['shellfish',afW("shrimp|prawns?|crab|lobster|scallops?|clams?|mussels?|oysters?|calamari|squid|crawfish")]];
const AF_PROT_ING:[string,RegExp][]=[['chicken',afW("chicken")],['turkey',afW("turkey")],['beef',afW("beef|steaks?|brisket|flank|sirloin|ribeye|chuck")],['pork',afW("pork|bacon|ham|sausages?|chorizo|pepperoni|salami|prosciutto|pancetta|ribs|hot dogs?|bratwurst")],['lamb',afW("lamb")],['fish',afW("salmon|tuna|cod|tilapia|trout|halibut|mahi|catfish|snapper|haddock|sardines?|swordfish|fish")],['shellfish',afW("shrimp|prawns?|crab|lobster|scallops?")]];
const AF_BROTH=/\b(?:chicken|beef|vegetable|veggie|turkey|bone|fish|seafood|mushroom|pork|ham|lamb)\s+(?:broth|stock|bouillon|base|consomm[eé])\b/g;
const AF_NONVEG=afW("chicken|turkey|beef|steaks?|brisket|pork|bacon|ham|sausages?|chorizo|pepperoni|salami|prosciutto|pancetta|lamb|veal|duck|venison|bison|hot dogs?|ribs|meatballs?|meatloaf|gelatin|lard|salmon|tuna|cod|tilapia|trout|halibut|mahi|catfish|snapper|haddock|sardines?|anchov(?:y|ies)|swordfish|fish|seafood|shrimp|prawns?|crab|lobster|scallops?|clams?|mussels?|oysters?|calamari|squid|crawfish");
function afMain(title:string,names:string[]):string{let best='',pos=1e9;for(const[k,re]of AF_PROT){const m=title.match(re);if(m&&m.index!==undefined&&m.index<pos){pos=m.index;best=k}}if(best)return best;if(/\b(?:eggs?|omelets?|omelettes?|frittatas?|quiche|scrambled)\b/.test(title))return'egg';const count:Record<string,number>={};names.forEach(n=>{const nb=n.replace(AF_BROTH,' ');for(const[k,re]of AF_PROT_ING)if(re.test(nb))count[k]=(count[k]||0)+1});let top='veg',n0=0;for(const[k]of AF_PROT_ING){if((count[k]||0)>n0){n0=count[k];top=k}}return top}

/* --- which meal does it suit? --- */
const AF_BREAKFAST=afW("breakfast|brunch|pancakes?|waffles?|omelets?|omelettes?|frittatas?|french toast|oatmeal|overnight oats|oats|granola|muffins?|scones?|biscuits and gravy|bagels?|hash browns?|hash|quiche|scrambled eggs?|egg bake|egg muffins?|egg cups?|crepes?|avocado toast|toast|cereal|parfait|shakshuka|huevos|chilaquiles|banana bread|yogurt bowl|smoothie bowl|sausage gravy");
const AF_LUNCH=afW("sandwich(?:es)?|wraps?|salads?|soups?|panini|subs?|melts?|sliders?|pinwheels?|hot dogs?|flatbread|pita|lettuce wraps?");
const AF_FLEX=afW("tacos?|burgers?|cheeseburgers?|burritos?|quesadillas?|pizza|chili|nachos|fajitas?|ramen|calzones?|bowls?");
const AF_DINNERY=afW("pasta|spaghetti|noodles?|casserole|lasagna|roast|stew|curry|stir[- ]?fry|bake|ziti|penne|fettuccine|macaroni|risotto|pot pie|dumplings|kabobs?|kebabs?|skewers|souvlaki|gyros?|meatballs?|meatloaf|ribs|enchiladas?|skillet|sheet pan|one pot|dinner|steaks?|chops?");
const afSafe=(r:Recipe):Recipe=>({...r,title:String(r.title||''),tags:(r.tags||[]).filter(x=>typeof x==='string'&&x.trim()),ingredients:(r.ingredients||[]).filter(x=>typeof x==='string'&&x.trim()),allergens:(r.allergens||[]).filter(x=>typeof x==='string'),instructions:r.instructions||[],servings:Number(r.servings)||4,time:Number(r.time)||30});
function afProfile(raw:Recipe):AFProfile{const r=afSafe(raw);const title=afClean(r.title),tags=afClean((r.tags||[]).join(' ')),all=title+' '+tags;const names=(r.ingredients||[]).map(x=>afClean(cleanIngredient(x)));const ing=names.join(' | ');const kind=afKind(title,all);const main=afMain(title,names);const veg=!AF_NONVEG.test(title+' '+ing);const dn=AF_DINNERY.test(all)||AF_PROT.some(([,re])=>re.test(title));return{r,title,tags,all,ing,names,kind,main,veg,b:AF_BREAKFAST.test(all),lo:AF_LUNCH.test(all),fx:AF_FLEX.test(all),dn}}
function afMealFit(p:AFProfile,meal:string):number{const time=p.r.time||30;if(meal==='Breakfast')return p.b?12:(p.lo||p.fx||p.dn?-20:-6);if(p.b)return-20;if(meal==='Lunch'){if(p.lo)return 12;if(p.fx)return 10;if(p.dn)return time<=35?4:-2;return 2}if(p.fx)return 10;if(p.lo)return 6;if(p.dn)return 12;return 2}
function afBlock(r:Recipe,prefs:Prefs):string{const w=warnings(afSafe(r),prefs);if(w.some(x=>x.startsWith('Allergy')))return'allergy';if(w.some(x=>x.startsWith('Avoid')))return'avoid';return''}

/* --- how much protein does one serving have? (estimated from the quantities in the ingredient list) --- */
const AF_P_SKIP=afW("broth|stock|seasoning|bouillon|gravy|sauce|soup|powder|salt|rub|spice|dressing|extract|flavou?r(?:ed|ing)?");
const AF_P_MEAT=afW("chicken|turkey|beef|steaks?|brisket|pork|bacon|ham|sausages?|lamb|veal|duck|salmon|tuna|cod|tilapia|trout|halibut|mahi|haddock|swordfish|fish|shrimp|prawns?|crab|lobster|scallops?|pepperoni|chorizo|flank|sirloin|ribeye|chuck|hot dogs?");
