function mergeOcr(chunks:string[]){let acc:string[]=[];chunks.forEach(c=>{const lines=c.split('\n').map(l=>l.trim()).filter(Boolean);if(!lines.length)return;if(!acc.length){acc=lines;return}const tail=Math.max(0,acc.length-60);let bestR=0,bestJ=-1;for(let j=0;j<Math.min(40,lines.length);j++){for(let i=tail;i<acc.length;i++){let r=0;while(j+r<lines.length&&i+r<acc.length&&sameLine(acc[i+r],lines[j+r]))r++;if(i+r<acc.length-2)continue;const longLine=r===1&&normLine(lines[j]).length>=28;if((r>=2||longLine)&&r>bestR){bestR=r;bestJ=j}}}acc=acc.concat(bestR?lines.slice(bestJ+bestR):lines)});return acc.join('\n')}
function Importer({close,save,initialUrl='' }:{close:()=>void;save:(r:Recipe)=>void;initialUrl?:string}){const pro=usePro();const[mode,setMode]=useState<'web'|'photo'|'paste'>('web');const[title,setTitle]=useState('');const[text,setText]=useState(initialUrl);const[status,setStatus]=useState('');const[working,setWorking]=useState(false);const[social,setSocial]=useState<{name:string;url:string}|null>(null);const[useAI,setUseAI]=saved<boolean>('piper.import.ai',true);const[pending,setPending]=useState<{recipe:Recipe;note:string;summary:string}|null>(null);const[notRecipe,setNotRecipe]=useState(false);const reviewRef=useRef<HTMLDivElement>(null);useEffect(()=>{if(pending||notRecipe)setTimeout(()=>reviewRef.current?.scrollIntoView({block:'nearest',behavior:'smooth'}),60)},[pending,notRecipe]);const[shots,setShots]=useState(0);const[handwritten,setHandwritten]=useState(false);const file=useRef<HTMLInputElement>(null);const cam=useRef<HTMLInputElement>(null);const sharedStarted=useRef(false);useEffect(()=>{if(initialUrl&&!sharedStarted.current){sharedStarted.current=true;void submit()}},[initialUrl]);function parsed(){return parseRecipeText(text)}async function scanFiles(list:File[]){const files=list.filter(f=>!f.type||f.type.startsWith('image/'));if(!files.length)return;setWorking(true);setPending(null);setNotRecipe(false);let worker:any=null;try{const{createWorker}=await import('tesseract.js');worker=await createWorker('eng');let acc=text;let added=0;for(let n=0;n<files.length;n++){setStatus(files.length>1?`Reading screenshot ${n+1} of ${files.length}…`:'Reading the photo…');const r=await worker.recognize(files[n]);const cleaned=cleanOcr(String(r?.data?.text||''));if(cleaned.trim()){acc=mergeOcr(acc.trim()?[acc,cleaned]:[cleaned]);added++;setText(acc)}}setShots(c=>c+added);setStatus(added?`Added ${added} screenshot${added===1?'':'s'}. If the recipe continues, add the next one. Otherwise review the text below.`:'Piper could not find any text in that image. Try a screenshot, or a brighter, straight-on photo.')}catch{setStatus('Could not read that image. Try a screenshot, or a brighter, straight-on photo.')}finally{try{await worker?.terminate()}catch{}setWorking(false)}}async function readHandwriting(list:File[]){const files=list.filter(f=>!f.type||f.type.startsWith('image/'));if(!files.length)return;if(!pro.isPro){setStatus('Reading handwriting is part of Piper Pro. Printed and typed cards still work with the switch off.');pro.openPaywall('general','pro');return}const gate=await pro.consumeAi();if(gate==='signin'){setStatus('Sign in (Prefs → Account & Sync) to read handwritten cards.');return}if(gate!=='ok')return;setWorking(true);setPending(null);setNotRecipe(false);setStatus(files.length>1?'Piper reads one handwritten card at a time. Reading the first photo… this can take up to 30 seconds.':'Reading the handwriting… this can take up to 30 seconds.');let d:HandDraft;try{d=await askHandwriting({image:await shrinkPhoto(files[0])})}catch(e:any){setStatus(e?.message||'Piper could not read that card. Try a brighter, straight-on photo.');setWorking(false);return}setWorking(false);const t=String(d.transcript||'').trim();if(t){setText(t);setShots(c=>c+1)}if(!d.isRecipe){setStatus(t?'Piper read the card but could not sort it into a recipe. Check the text below and fix anything it misread.':'Piper could not find any writing in that photo. Try a brighter, straight-on photo.');if(t)setNotRecipe(true);return}await organize(d)}function pickImages(e:React.ChangeEvent<HTMLInputElement>){const fs:File[]=Array.from(e.target.files||[]) as File[];e.target.value='';if(fs.length)void(handwritten?readHandwriting(fs):scanFiles(fs))}function startOver(){setText('');setShots(0);setStatus('');setPending(null);setNotRecipe(false)}async function submit(){if(mode==='web'){const net=socialSource(text);if(net){if(!pro.guardFeature('socialImport'))return;setSocial({name:net,url:text.trim()});setMode('paste');setText('');setTitle('');setStatus(`${net} posts can’t be read automatically. Copy the caption (or the recipe from the comments) and paste it below. If the post will not let you copy, use screenshots instead. Piper keeps the link.`);return}setWorking(true);setStatus('Finding recipe...');try{const r=await scrapeRecipe(text);save({id:crypto.randomUUID(),title:r.title||'Imported Recipe',image:r.image||'',servings:r.servings||4,favorite:false,time:r.time||30,allergens:[],tags:r.tags?.length?r.tags:['Imported'],ingredients:r.ingredients?.length?r.ingredients:['Add ingredients'],instructions:r.instructions?.length?r.instructions:['Add instructions'],sourceName:r.sourceName,sourceUrl:r.sourceUrl})}catch(e:any){setStatus(e?.message||'Piper could not import that recipe webpage.')}finally{setWorking(false)}return}if(useAI&&text.trim().length>=15){await organize();return}save(localRecipe())}function localRecipe():Recipe{const p=parsed();return{id:crypto.randomUUID(),title:title.trim()||p.title||'Imported Recipe',image:'',servings:4,favorite:false,time:30,allergens:[],tags:social?['Imported',social.name]:['Imported'],ingredients:p.ingredients.length?p.ingredients:['Add ingredients'],instructions:p.instructions.length?p.instructions:['Add instructions'],...(social?{sourceName:social.name,sourceUrl:social.url}:{})}}function aiRecipe(d:CaptionDraft):Recipe{const base=social?['Imported',social.name]:['Imported'];const extra=(d.tags||[]).filter(t=>t&&!base.some(b=>b.toLowerCase()===t.toLowerCase()));return{id:crypto.randomUUID(),title:title.trim()||d.title||'Imported Recipe',image:'',servings:d.servings>0?d.servings:4,favorite:false,time:d.time>0?d.time:30,allergens:[],tags:[...base,...extra].slice(0,6),ingredients:d.ingredients.length?d.ingredients:['Add ingredients'],instructions:d.instructions.length?d.instructions:['Add instructions'],...(d.notes?{notes:'From the post: '+d.notes}:{}),...(social?{sourceName:social.name,sourceUrl:social.url}:{})}}async function organize(pre?:CaptionDraft){if(!pre){const gate=await pro.consumeAi();if(gate==='limit')return;if(gate==='signin'){setStatus('Sign in to use Piper’s Chef. Using Piper’s simple organizer instead.');save(localRecipe());return}}setWorking(true);setNotRecipe(false);setPending(null);setStatus('Piper’s Chef is organizing the text…');try{const d=pre||await askCaption({text:text.slice(0,8000),kind:mode==='photo'?'scan':'caption',source:social?.name||''});if(!d.isRecipe){setStatus('');setNotRecipe(true);return}const r=aiRecipe(d);const miss=d.missing||[];const n=d.ingredients.length,m=d.instructions.length;const summary=`Found ${n} ingredient${n===1?'':'s'} and ${m} step${m===1?'':'s'}.`;if(miss.length||d.dropped){const parts:string[]=[];if(miss.includes('steps'))parts.push('The post did not include the steps. They may be in the comments or the video, so you can add them in the editor.');if(miss.includes('ingredients'))parts.push('The post did not include an ingredient list. You can add it in the editor.');if(d.dropped)parts.push(`${d.dropped} ingredient${d.dropped===1?' was':'s were'} left out because the post did not mention ${d.dropped===1?'it':'them'}.`);setStatus('');setPending({recipe:r,note:parts.join(' '),summary});return}save(r)}catch{setStatus('');save(localRecipe())}finally{setWorking(false)}}return <div className="modal" role="dialog" aria-modal="true"><div className="modal-card"><div className="modal-head"><div><h2>{social?`Add from ${social.name}`:initialUrl?'Import shared recipe':'Add a recipe'}</h2><p>{social?`Saving from ${social.name}. Paste the caption or add screenshots and Piper will organize it.`:initialUrl?'Piper is reading the recipe you shared. Review it before saving.':'Use a website, scan a card or paste the recipe.'}</p></div><button aria-label="Close" onClick={close}><X/></button></div><div className="mode-tabs">{(['web','photo','paste']as const).map(m=><button key={m} className={mode===m?'active':''} onClick={()=>{setMode(m);setStatus('');setText('');setTitle('');setSocial(null);setPending(null);setNotRecipe(false);setShots(0)}}>{m==='web'?'Web URL':m==='photo'?'Photo / card':'Copy & paste'}</button>)}</div>{mode!=='web'&&<><label>Recipe title (optional)</label><input value={title} onChange={e=>setTitle(e.target.value)} placeholder="Piper can add a title later"/></>}{mode==='web'&&<><label>Recipe webpage</label><input type="url" enterKeyHint="go" value={text} onChange={e=>setText(e.target.value)} placeholder="https://example.com/recipe" aria-label="Recipe web address" autoComplete="off"/><small>Paste a recipe webpage address and Piper imports the title, photo, ingredients and steps. Facebook, TikTok and Instagram links work too: Piper will guide you through pasting the caption.</small></>}{mode==='photo'&&<>{social&&<div className="social-banner"><span>From {social.name}</span><a href={social.url} target="_blank" rel="noreferrer"><ExternalLink/>Open post</a></div>}<input ref={file} type="file" accept="image/*" multiple hidden onChange={pickImages}/><input ref={cam} type="file" accept="image/*" capture="environment" hidden onChange={pickImages}/>{!social&&<><label className="hand-toggle"><input type="checkbox" checked={handwritten} disabled={working} onChange={e=>{setHandwritten(e.target.checked);setStatus('')}}/><span>This card is handwritten</span>{!pro.isPro&&<em className="pro-chip">Pro</em>}</label><small className="hand-note">✍️ Handwriting is less consistent than typed or printed cards. Piper does its best, but always check the ingredients and amounts before you save.{handwritten?' One card per photo, straight-on, in good light.':''}</small></>}<div className="scan-buttons"><button className="secondary scan" disabled={working} onClick={()=>file.current?.click()}><ImageIcon/>{handwritten?'Choose a photo of the card':shots?'Add next screenshot':'Choose screenshots or photos'}</button><button className="secondary scan" disabled={working} onClick={()=>cam.current?.click()}><Camera/>Take a photo</button></div>{!handwritten&&<small className="scan-tip"><b>Recipe too long for one screen?</b> Take screenshots from top to bottom (they can overlap) and add them one after another. Tap “See more” on the post first so the whole caption shows. Piper puts them in order and skips repeated lines.</small>}{shots>0&&<div className="scan-count"><span>{shots} screenshot{shots===1?'':'s'} added</span><button type="button" className="text-link" disabled={working} onClick={startOver}>Start over</button></div>}<textarea value={text} onChange={e=>{setText(e.target.value);setPending(null);setNotRecipe(false)}} placeholder="The text Piper reads from your screenshots appears here. You can edit it."/></>}{mode==='paste'&&<>{social&&<div className="social-banner"><span>From {social.name}</span><a href={social.url} target="_blank" rel="noreferrer"><ExternalLink/>Open post</a></div>}<button type="button" className="cant-copy" onClick={()=>{setMode('photo');setText('');setStatus('');setShots(0);setPending(null);setNotRecipe(false)}}><ImageIcon/>Can’t copy the text? Use screenshots instead</button><label>Full recipe</label><textarea value={text} onChange={e=>{setText(e.target.value);setPending(null);setNotRecipe(false)}} placeholder={'Paste the caption or recipe here.\n\nPiper finds the ingredients and steps, and uses the first line as the title.'}/></>}{mode!=='web'&&<><label className="toggle-row ai-toggle"><input type="checkbox" checked={useAI} onChange={e=>{setUseAI(e.target.checked);setPending(null);setNotRecipe(false)}}/> Let Piper’s Chef (AI) organize this text</label><small className="ai-note">{useAI?'The text you paste is sent to Piper’s AI service to find the ingredients and steps. Nothing else is shared.':'Piper will sort the text with its simple organizer, which works best when the post has Ingredients and Directions headings.'}</small></>}{status&&<small role="status">{status}</small>}{notRecipe&&<div className="import-review soft" ref={reviewRef} role="alert"><b>That does not look like a recipe.</b><span>Piper could not find ingredients or steps. Paste the caption that lists them, or check the comments for the recipe.</span><button className="secondary" onClick={()=>{setNotRecipe(false);save(localRecipe())}}>Use my text as is</button></div>}{pending&&<div className="import-review" ref={reviewRef} role="status"><b>✓ {pending.summary}</b>{!!pending.note&&<span>{pending.note}</span>}<span>Review everything in the editor before saving.</span><button className="primary wide" onClick={()=>save(pending.recipe)}>Review &amp; edit</button></div>}{!pending&&<button className="primary wide" disabled={working||!text.trim()} onClick={submit}>{working?<><i className="spin"/>{mode==='web'?'Importing recipe…':useAI?'Organizing…':'Reading…'}</>:(mode==='web'?'Import Recipe':useAI?'Organize with Piper’s Chef':'Continue')}</button>}</div></div>}
function Editor({recipe,save,cancel}:{recipe:Recipe;save:(r:Recipe)=>void;cancel:()=>void}){const[d,setD]=useState(recipe);const[search,setSearch]=useState(false);const[imageFailed,setImageFailed]=useState(!recipe.image);const q=encodeURIComponent(`${d.title} ${d.ingredients.slice(0,3).join(' ')} recipe`);function choosePhoto(f?:File){if(f){setD({...d,image:URL.createObjectURL(f)});setImageFailed(false)}}return <div className="editor content"><div className="modal-head"><h1>Edit recipe</h1><button aria-label="Close" onClick={cancel}><X/></button></div><label>Title</label><input value={d.title} onChange={e=>setD({...d,title:e.target.value})}/>{!imageFailed&&d.image?<img className="edit-photo" src={d.image} onError={()=>setImageFailed(true)}/>:<div className="image-fallback"><ImageIcon/><b>Image unavailable</b><span>This recipe's image can't be imported from the original website. You can upload your own photo now or add one later.</span></div>}<div className="action-row"><label className="secondary wide"><Upload/>Upload photo<input hidden type="file" accept="image/*" onChange={e=>choosePhoto(e.target.files?.[0])}/></label><button className="secondary wide" onClick={()=>setSearch(!search)}><Search/>Web search</button></div>{search&&<div className="pref-card"><a className="primary" target="_blank" rel="noreferrer" href={`https://www.bing.com/images/search?q=${q}`}><ExternalLink/>Search title + ingredients</a><label>Paste selected image URL</label><input value={d.image} onChange={e=>{setD({...d,image:e.target.value});setImageFailed(false)}}/></div>}<label>Ingredients</label><textarea value={d.ingredients.join('\n')} onChange={e=>setD({...d,ingredients:e.target.value.split('\n').filter(Boolean)})}/><label>Instructions</label><small className="field-help">Steps will be numbered automatically when you save.</small><textarea value={d.instructions.join('\n')} onChange={e=>setD({...d,instructions:e.target.value.split('\n').filter(Boolean)})}/><button className="primary wide" onClick={()=>save(d)}>Save changes</button></div>}
function warnings(r:Recipe,p:Prefs){const text=(' '+r.ingredients.join(' ')+' '+r.allergens.join(' ')+' ').toLowerCase();const dairyText=text.replace(/peanut butter|almond butter|cashew butter|cocoa butter|sunflower seed butter|coconut milk|almond milk|oat milk|soy milk|coconut cream|cream of tartar/g,' ');const glutenText=text.replace(/almond flour|coconut flour|rice flour|rice noodles?|corn tortillas?/g,' ');const allergyTerms:Record<string,string[]>={Dairy:['milk','cream','butter','cheese','mozzarella','cheddar','parmesan','ricotta','yogurt','whey','casein','ghee','half and half','half-and-half'],Eggs:['egg','eggs','mayonnaise','meringue'],Peanuts:['peanut','peanuts','peanut butter'],"Tree nuts":['almond','cashew','walnut','pecan','pistachio','hazelnut','macadamia','brazil nut','pine nut'],Soy:['soy','soybean','tofu','tempeh','edamame','miso','soy sauce'],Gluten:['wheat','flour','bread','pasta','noodle','cracker','breadcrumbs','bread crumbs','barley','rye'],Fish:['salmon','tuna','cod','tilapia','trout','anchovy','sardine','fish'],Shellfish:['shrimp','prawn','crab','lobster','clam','mussel','oyster','scallop','shellfish'],Sesame:['sesame','tahini']};const avoidTerms:Record<string,string[]>={'spicy food':['jalapeno','jalapeño','serrano','habanero','chili','chile','cayenne','sriracha','hot sauce','red pepper flakes','crushed red pepper'],seafood:[...allergyTerms.Fish,...allergyTerms.Shellfish]};const esc=(v:string)=>v.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');const boundary=(term:string,src=text)=>{const t=term.toLowerCase().trim();const variants=Array.from(new Set([t,t.replace(/s$/,''),t.replace(/es$/,'')])).filter(v=>v.length>2);return variants.some(v=>new RegExp(`(^|[^a-z])${esc(v)}(?:s|es)?([^a-z]|$)`,'i').test(src))};const detectedAllergies=p.allergies.filter(pref=>{const key=Object.keys(allergyTerms).find(k=>k.toLowerCase()===pref.toLowerCase())||pref;const terms=allergyTerms[key]||[pref];const src=key==='Dairy'?dairyText:key==='Gluten'?glutenText:text;return terms.some(t=>boundary(t,src))||r.allergens.some(a=>a.toLowerCase().includes(pref.toLowerCase())||pref.toLowerCase().includes(a.toLowerCase()))});const detectedAvoid=p.dislikes.filter(pref=>(avoidTerms[pref.toLowerCase()]||[pref]).some(t=>boundary(t)));return[...detectedAllergies.map(x=>'Allergy: '+x),...detectedAvoid.map(x=>'Avoid: '+x)]}
const UNI_FRAC:Record<string,number>={'¼':.25,'½':.5,'¾':.75,'⅓':1/3,'⅔':2/3,'⅛':.125,'⅜':.375,'⅝':.625,'⅞':.875};
const QTY_NUM='(?:\\d+\\s+\\d+\\/\\d+|\\d+\\/\\d+|\\d+(?:\\.\\d+)?(?:\\s?[¼½¾⅓⅔⅛⅜⅝⅞])?|[¼½¾⅓⅔⅛⅜⅝⅞])';
const QTY_RE=new RegExp('^('+QTY_NUM+')(?:(\\s*(?:-|–|to)\\s*)('+QTY_NUM+'))?');
function parseQty(t:string){t=t.trim();let m=t.match(/^(\d+)\s+(\d+)\/(\d+)$/);if(m)return +m[1]+ +m[2]/ +m[3];m=t.match(/^(\d+)\/(\d+)$/);if(m)return +m[1]/ +m[2];m=t.match(/^(\d+(?:\.\d+)?)\s?([¼½¾⅓⅔⅛⅜⅝⅞])$/);if(m)return +m[1]+UNI_FRAC[m[2]];if(UNI_FRAC[t]!==undefined)return UNI_FRAC[t];return parseFloat(t)}
function formatQty(n:number){const FR:[number,string][]=[[1/8,'1/8'],[1/4,'1/4'],[1/3,'1/3'],[3/8,'3/8'],[1/2,'1/2'],[5/8,'5/8'],[2/3,'2/3'],[3/4,'3/4'],[7/8,'7/8']];let whole=Math.floor(n+1e-9);const frac=n-whole;if(frac<.04)return String(whole||Math.round(n*100)/100);if(frac>.96)return String(whole+1);let best=FR[0],diff=Infinity;for(const f of FR){const d=Math.abs(f[0]-frac);if(d<diff){diff=d;best=f}}if(diff<=.03)return whole?whole+' '+best[1]:best[1];return String(Math.round(n*100)/100)}
function scaleIngredient(t:string,s:number){if(s===1)return t;const m=t.match(QTY_RE);if(!m)return t;const first=parseQty(m[1]);if(!isFinite(first))return t;let out=formatQty(first*s);if(m[2]&&m[3]){const second=parseQty(m[3]);if(isFinite(second))out+=m[2]+formatQty(second*s);else return t}return out+t.slice(m[0].length)}
